svg.script:
    const frame = document.getElementById("linux_frame");

    const storageShim = `<style>
      body, html { margin: 0 !important; padding: 0 !important; background: #000 !important; color: #eee; font-family: sans-serif; overflow: hidden !important; height: 100%; display: flex; flex-direction: column; }
      #bar { padding: 8px 12px; background: #181818; border-bottom: 1px solid #333; display: flex; gap: 10px; align-items: center; font-size: 13px; }
      button { background: #2b2b2b; color: #fff; border: 1px solid #444; padding: 4px 12px; border-radius: 4px; cursor: pointer; }
      button:hover { background: #3a3a3a; }
      #cv { flex: 1; width: 100%; height: 100%; background: #000; object-fit: contain; }
      #info { margin-left: auto; color: #7f7; font-family: monospace; }
    </style>
    <script>
      try { window.localStorage.getItem("t"); } catch (e) {
        const mem = {};
        Object.defineProperty(window, "localStorage", { value: {
          getItem: k => mem[k] || null,
          setItem: (k, v) => { mem[k] = String(v); },
          removeItem: k => { delete mem[k]; },
          clear: () => { for (const k in mem) delete mem[k]; }
        }});
      }
      try { document.cookie; } catch (e) {
        let c = "";
        Object.defineProperty(document, "cookie", { get: () => c, set: v => { c = v; } });
      }
    <\/script>`;

    const playerBody = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8" />${storageShim}</head>
<body>
  <div id="bar">
    <input type="file" id="file" accept=".mkv,.webm" />
    <button id="play">Play / Pause</button>
    <button id="restart">Restart</button>
    <span id="info">Select a local .mkv / .webm file</span>
  </div>
  <canvas id="cv"></canvas>
  <script>
    const cv = document.getElementById("cv");
    const ctx = cv.getContext("2d");
    const info = document.getElementById("info");
    let playing = false, timer = null, frames = [], tracks = [], idx = 0, dec = null;

    function readVint(u8, pos) {
      let b = u8[pos], len = 1, mask = 0x80;
      while (len <= 8 && !(b & mask)) { mask >>= 1; len++; }
      let val = b & (mask - 1);
      for (let i = 1; i < len; i++) val = (val * 256) + u8[pos + i];
      return { val, len };
    }

    function parseMkv(buf) {
      const u8 = new Uint8Array(buf), outTracks = [], outFrames = [];
      let p = 0, clusterTs = 0;
      while (p < u8.length - 4) {
        const b0 = u8[p], b1 = u8[p + 1], b2 = u8[p + 2], b3 = u8[p + 3];
        const isSeg = (b0 === 0x18 && b1 === 0x53 && b2 === 0x80 && b3 === 0x67);
        const isTrk = (b0 === 0x16 && b1 === 0x54 && b2 === 0xAE && b3 === 0x6B);
        const isCls = (b0 === 0x1F && b1 === 0x43 && b2 === 0xB6 && b3 === 0x75);
        const isHdr = (b0 === 0x1A && b1 === 0x45 && b2 === 0xDF && b3 === 0xA3);
        if (isSeg || isTrk || isCls || isHdr) {
          p += 4;
          const sz = readVint(u8, p);
          p += sz.len;
          if (isSeg) continue;
          const end = Math.min(u8.length, p + sz.val);
          if (isTrk) {
            const txt = new TextDecoder().decode(u8.subarray(p, end));
            const m = txt.match(/(V_MPEG4\\/ISO\\/AVC|V_MPEGH\\/ISO\\/HEVC|V_VP8|V_VP9|V_AV1|A_AAC|A_OPUS|A_VORBIS)/g);
            if (m) outTracks.push(...m);
          } else if (isCls) {
            let cp = p;
            while (cp < end - 3) {
              const tag = u8[cp++];
              const s = readVint(u8, cp);
              cp += s.len;
              if (tag === 0xE7) {
                clusterTs = 0;
                for (let i = 0; i < s.val; i++) clusterTs = clusterTs * 256 + u8[cp + i];
              } else if (tag === 0xA3) {
                const trk = readVint(u8, cp);
                const relTs = (u8[cp + trk.len] << 8) | u8[cp + trk.len + 1];
                const flags = u8[cp + trk.len + 2];
                const hdr = trk.len + 3;
                if (trk.val === 1) {
                  outFrames.push({
                    ts: (clusterTs + relTs) * 1000,
                    key: !!(flags & 0x80),
                    data: u8.subarray(cp + hdr, cp + s.val)
                  });
                }
              }
              cp += s.val;
            }
          }
          p = end;
        } else {
          p++;
        }
      }
      return { tracks: outTracks, frames: outFrames };
    }

    function startDecoder() {
      if (dec) { try { dec.close(); } catch (e) {} }
      const codec = tracks.includes("V_VP9") ? "vp09.00.10.08" :
                    tracks.includes("V_VP8") ? "vp8" :
                    tracks.includes("V_AV1") ? "av01.0.04M.08" : "avc1.64001f";
      dec = new VideoDecoder({
        output: f => {
          cv.width = f.displayWidth;
          cv.height = f.displayHeight;
          ctx.drawImage(f, 0, 0);
          f.close();
        },
        error: err => { info.textContent = "Codec error: " + err.message; }
      });
      dec.configure({ codec });
      idx = 0;
      playing = true;
      clearInterval(timer);
      timer = setInterval(() => {
        if (!playing || idx >= frames.length) return;
        const fr = frames[idx++];
        try {
          dec.decode(new EncodedVideoChunk({
            type: fr.key ? "key" : "delta",
            timestamp: fr.ts,
            data: fr.data
          }));
        } catch (e) {}
      }, 33);
    }

    document.getElementById("file").onchange = async (e) => {
      const f = e.target.files[0];
      if (!f) return;
      info.textContent = "Parsing EBML...";
      const res = parseMkv(await f.arrayBuffer());
      tracks = res.tracks;
      frames = res.frames;
      info.textContent = "Tracks: " + (tracks.join(", ") || "Unknown") + " | Frames: " + frames.length;
      if (!("VideoDecoder" in window)) {
        info.textContent += " (WebCodecs unavailable)";
        return;
      }
      if (frames.length) startDecoder();
    };

    document.getElementById("play").onclick = () => { playing = !playing; };
    document.getElementById("restart").onclick = () => { if (frames.length) startDecoder(); };
    window.addEventListener("keydown", e => {
      if (e.code === "Space") { e.preventDefault(); playing = !playing; }
    });
  <\/script>
</body>
</html>`;

    const win = frame.contentWindow;
    const doc = frame.contentDocument || win.document;
    doc.open();
    doc.write(playerBody);
    doc.close();
    win.focus();
